Types.Decl:
type EditView struct {
	Title   string
	BackURL string
	// BackLabel names the list BackURL leads to, as a translation key.
	BackLabel string
	// Warnings point out chains of redirects.
	Warnings []string
	// Saved is set for an existing redirect, which has hits.
	Saved   bool
	Hits    int64
	LastHit string
	Form    form.RenderModel
	Errors  form.FieldErrors
	Delete  *form.RenderModel
}

type ImportView struct {
	Title   string
	BackURL string
	// Problems lists the refused lines; nothing was imported.
	Problems []string
	Form     form.RenderModel
	Errors   form.FieldErrors
}

type IndexRow struct {
	URL     string
	From    string
	To      string
	Status  int
	Hits    int64
	LastHit string
	// Chained is set when To leads to another redirect.
	Chained bool
}

type IndexView struct {
	Title     string
	NewURL    string
	ImportURL string
	MissedURL string
	// TrashURL shows the deleted redirects in the admin's trash.
	TrashURL string
	// TestURL is where the test box sends ?test=<path>.
	TestURL string
	// TestForm is the test box, a form that gets TestURL.
	TestForm form.RenderModel
	Test     *TestResult
	Rows     []IndexRow
	// Pager pages through long lists.
	Pager admin.Pager
}

type LineError struct {
	Line int
	Err  error
}

type Miss struct {
	Path    string    `db:"path"`
	Hits    int64     `db:"hits"`
	LastHit time.Time `db:"last_hit_at"`
}

type MissedRow struct {
	Path    string
	Hits    int64
	LastHit string
	// AddURL opens a new redirect for the path; empty without the right.
	AddURL string
}

type MissedView struct {
	Title   string
	BackURL string
	Rows    []MissedRow
	Clear   *form.RenderModel
}

type Redirect struct {
	ID string `db:"id"`
	// From is the normalised old path, for example "/old-page".
	From string `db:"from_path"`
	// To is a path on the site, such as "/en/news", or an absolute URL.
	To      string     `db:"to_url"`
	Status  int        `db:"status"`
	Hits    int64      `db:"hits"`
	LastHit *time.Time `db:"last_hit_at"`
	// CreatedAt is when the redirect was added, CreatedBy by whom (empty for
	// the system).
	CreatedAt time.Time `db:"created_at"`
	CreatedBy db.Ref    `db:"created_by"`
	// UpdatedAt and UpdatedBy are the last change by an editor; hits do not
	// count as changes.
	UpdatedAt time.Time `db:"updated_at"`
	UpdatedBy db.Ref    `db:"updated_by"`
	// DeletedAt is set while the redirect is in the trash, with DeletedBy.
	DeletedAt *time.Time `db:"deleted_at"`
	DeletedBy db.Ref     `db:"deleted_by"`
}

type Service struct {
	// contains unexported fields
}

type TestResult struct {
	Path     string
	Reserved bool
	Steps    []IndexRow
}
